using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.CustomerContacts.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;
namespace Namaa.Application.CustomerContacts.Commands.UpdateCustomerContact;
public sealed class UpdateCustomerContactCommandHandler(ICustomerRepository repository,IApplicationDbContext dbContext):IRequestHandler<UpdateCustomerContactCommand,Result<CustomerContactDto>>
{public async Task<Result<CustomerContactDto>> Handle(UpdateCustomerContactCommand request,CancellationToken cancellationToken){var customer=await repository.FindForUpdateWithContactsAsync(request.CustomerId,cancellationToken);if(customer is null)return Result.Failure<CustomerContactDto>(CustomerContactErrors.CustomerNotFound);var contact=customer.Contacts.SingleOrDefault(x=>x.Id==request.Id);if(contact is null)return Result.Failure<CustomerContactDto>(CustomerContactErrors.NotFound);contact.Update(request.FullName,request.Email,request.PhoneNumber,request.JobTitle);if(request.IsPrimary)customer.SetPrimaryContact(contact);else if(contact.IsPrimary)return Result.Failure<CustomerContactDto>(new Error("CustomerContacts.PrimaryRequired","Use another contact as primary before clearing the current primary contact.",ErrorType.Conflict));await dbContext.SaveChangesAsync(cancellationToken);return Result.Success(CustomerContactDto.FromEntity(contact));}}

